def fizzbuzz(n):
    """
    Devuelve una lista de strings del 1 al n, donde los multiplos de 3 son 'Fizz', los de 5 'Buzz' y los de ambos 'FizzBuzz'. El resto, el numero como string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def rotar(lista, n):
    if not lista:
        return lista
    longitud = len(lista)
    n = n % longitud
    if n < 0:
        n = n + longitud
    return lista[-n:] + lista[:-n]

def a_romano(n):
    if not 1 <= n <= 3999:
        raise ValueError("El número debe estar entre 1 y 3999")

    roman_map = { 1: 'I', 4: 'IV', 5: 'V', 9: 'IX', 10: 'X', 40: 'XL', 50: 'L', 90: 'XC', 100: 'C', 400: 'CD', 500: 'D', 900: 'CM', 1000: 'M'}
    i = 12
    result = ""

    while n != 0:
        if list(roman_map.keys())[i] <= n:
            result += list(roman_map.values())[i]
            n -= list(roman_map.keys())[i]
        else:
            i -= 1

    return result

def desde_romano(s):
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and roman_map[s[i]] < roman_map[s[i+1]]:
            result -= roman_map[s[i]]
        else:
            result += roman_map[s[i]]
        i += 1
    return result

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales y devuelve la tupla (elemento, longitud).
    Si hay empate devuelve la primera. Con lista vacía devuelve None.
    """
    if not lista:
        return None

    max_len = 0
    max_element = None
    current_len = 1
    current_element = lista[0]

    for i in range(1, len(lista)):
        if lista[i] == current_element:
            current_len += 1
        else:
            if current_len > max_len:
                max_len = current_len
                max_element = current_element
            current_element = lista[i]
            current_len = 1

    if current_len > max_len:
        max_len = current_len
        max_element = current_element

    return (max_element, max_len)

def a_camel(s):
    words = s.split('_')
    result = ""
    for i, word in enumerate(words):
        if i == 0:
            result += word.lower()
        else:
            result += word[0].upper() + word[1:]
    return result

import re

def a_snake(s):
    s = re.sub('(.)([A-Z][a-z]+)', r'\1_\2', s)
    s = re.sub('([a-z0-9])([A-Z])', r'\1_\2', s)
    return s.lower()

def primos(n):
  """
  Devuelve la lista ordenada de todos los números primos menores o iguales a n.
  Si n es menor que 2 devuelve lista vacía.
  """
  if n < 2:
    return []

  primos_lista = []
  for i in range(2, n + 1):
    es_primo = True
    for j in range(2, int(i**0.5) + 1):
      if i % j == 0:
        es_primo = False
        break
    if es_primo:
      primos_lista.append(i)

  return sorted(primos_lista)

def mcd(a, b):
  """
  Devuelve el máximo común divisor de dos enteros no negativos.
  El mcd de un número con 0 es ese número.
  """
  if b == 0:
    return a
  return mcd(b, a % b)

def fusionar(intervalos):
    """
    Fusiona una lista de intervalos, ordenados por inicio.
    Dos intervalos que se tocan en un extremo se fusionan.
    """
    intervalos.sort()
    resultado = []
    for intervalo in intervalos:
        if not resultado or intervalo[0] > resultado[-1][1]:
            resultado.append(intervalo)
        else:
            resultado[-1] = (resultado[-1][0], max(resultado[-1][1], intervalo[1]))
    return resultado

def comprimir(s):
    """
    Aplica codificación por repeticiones: 'aaabb' se convierte en 'a3b2'.
    Devuelve la versión comprimida solo si es más corta que la original;
    si no lo es, devuelve la original sin cambios.
    """
    if not s:
        return s

    comprimida = ""
    count = 1
    for i in range(len(s)):
        if i + 1 < len(s) and s[i] == s[i+1]:
            count += 1
        else:
            comprimida += s[i] + str(count)
            count = 1

    return comprimida if len(comprimida) < len(s) else s

def balanceado(texto):
    """
    Devuelve True si los parentesis, corchetes y llaves del texto estan correctamente balanceados y anidados.
    Un texto vacio esta balanceado.
    """
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for char in texto:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if mapping[char] != top:
                return False
    return not stack

def transpuesta(m):
    """
    Recibe una matriz como lista de listas y devuelve su transpuesta.
    Con matriz vacia devuelve lista vacia.
    """
    if not m:
        return []

    max_columna = max(len(fila) for fila in m)
    transpuesta_matriz = []
    for i in range(max_columna):
        nueva_fila = []
        for fila in m:
            if i < len(fila):
                nueva_fila.append(fila[i])
        transpuesta_matriz.append(nueva_fila)
    return transpuesta_matriz

