def n_esimo_mayor(lista, n):
    """
    Devuelve el n-esimo valor mas grande contando valores DISTINTOS (los repetidos cuentan una sola vez).
    Si no hay suficientes valores distintos devuelve None.
    """
    valores_distintos = sorted(list(set(lista)), reverse=True)
    if n > len(valores_distintos):
        return None
    else:
        return valores_distintos[n-1]

def formatear_bytes(n):
    """
    Convierte una cantidad de bytes a texto legible usando base 1024 y las unidades B, KB, MB, GB.
    Los bytes se muestran sin decimales y las demas unidades con UN decimal.
    """
    if n == 0:
        return "0 B"

    texto = []

    if n < 1024:
        texto.append(str(n) + " B")
    elif n < 1024 * 1024:
        texto.append(str(round(n / 1024, 1)) + " KB")
    elif n < 1024 * 1024 * 1024:
        texto.append(str(round(n / (1024 * 1024), 1)) + " MB")
    else:
        texto.append(str(round(n / (1024 * 1024 * 1024), 1)) + " GB")

    return " ".join(texto)

