def dedup(lista):
  """Elimina duplicados de una lista, conservando el orden de la primera aparición."""
  seen = set()
  result = []
  for item in lista:
    if item not in seen:
      seen.add(item)
      result.append(item)
  return result

def anidar(plano):
    """
    Convierte un dict de claves con puntos en un dict anidado.
    Ej: {'a.b': 1} -> {'a': {'b': 1}}
    """
    resultado = {}
    for clave, valor in plano.items():
        clave_partes = clave.split('.')
        if len(clave_partes) == 2:
            nombre_nivel = clave_partes[0]
            nombre_subnivel = clave_partes[1]
            if nombre_nivel not in resultado:
                resultado[nombre_nivel] = {}
            resultado[nombre_nivel][nombre_subnivel] = valor
        else:
            resultado[clave_partes[0]] = valor
    return resultado

def promedio_movil(nums, ventana):
    if len(nums) < ventana:
        return []

    resultados = []
    for i in range(len(nums) - ventana + 1):
        suma = sum(nums[i:i+ventana])
        promedio = suma / ventana
        resultados.append(promedio)
    return resultados

def formatear_bytes(n):
    """
    Convierte un número de bytes a texto legible usando múltiplos de 1024 y las unidades B, KB, MB, GB.
    Con un decimal, salvo para B que va sin decimales.
    Ej: 1536 -> '1.5 KB'
    """
    if n < 1024:
        return str(n) + ' B'
    elif n < 1024 * 1024:
        return str(n // 1024) + ' KB'
    elif n < 1024 * 1024 * 1024:
        return str(n // (1024 * 1024)) + ' MB'
    else:
        return str(n // (1024 * 1024 * 1024)) + ' GB'

def parsear_query(s):
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}

    result = {}
    pairs = s.split('&')
    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=')
            result[key] = value
        else:
            result[pair] = ""
    return result

def validar_password(p):
  """
  Valida si una contraseña cumple con los siguientes requisitos:
  - Al menos 8 caracteres.
  - Al menos una mayúscula.
  - Al menos una minúscula.
  - Al menos un dígito.
  - Al menos un carácter que no sea alfanumérico.
  """
  if len(p) < 8:
    return False
  if not any(c.isupper() for c in p):
    return False
  if not any(c.islower() for c in p):
    return False
  if not any(c.isdigit() for c in p):
    return False
  if not any(not c.isalnum() for c in p):
    return False
  return True

def a_base(n, base):
    if n == 0:
        return "0"
    digits = "0123456789abcdef"
    result = ""
    while n > 0:
        result = digits[n % base] + result
        n //= base
    return result

def pares_primero(nums):
  """
  Devuelve una lista con los pares primero y los impares despues,
  conservando el orden relativo original dentro de cada grupo.
  """
  pares = []
  impares = []
  for num in nums:
    if num % 2 == 0:
      pares.append(num)
    else:
      impares.append(num)
  return pares + impares

def interseccion(a, b):
    """
    Devuelve la lista ordenada de valores presentes en ambas listas, sin repetidos.
    """
    resultado = []
    i = 0
    j = 0
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            if not resultado or a[i] != resultado[-1]:
                resultado.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return resultado

def campo_csv(s):
  """
  Prepara un campo para CSV: si contiene coma, comilla doble o salto de linea,
  lo devuelve entre comillas dobles y con las comillas internas duplicadas.
  Si no, lo devuelve tal cual.
  """
  if ',' in s or '"' in s or '\n' in s:
    return '"' + s.replace('"', '""') + '"'
  else:
    return s

