def obtener(d, camino, defecto=None):
    """
    Busca en un dict anidado siguiendo un camino con puntos ('a.b.c') y devuelve el valor, o el defecto si algun tramo no existe.
    """
    for parte in camino:
        if parte not in d:
            return defecto
        d = d[parte]
    return d

import functools

def con_reintentos(fn, veces):
    """
    Ejecuta fn() y, si lanza una excepción, la reintenta hasta 'veces' intentos en total.
    Si todos fallan, vuelve a lanzar la última excepción.
    Devuelve el resultado si alguno funciona.
    """
    reintentos = 0
    while reintentos < veces:
        try:
            return fn()
        except Exception as e:
            reintentos += 1
            if reintentos == veces:
                raise e
    raise RuntimeError("Se agotaron los reintentos")
